void heapSort(int arr[], int n) {
    for (int i = n/2 - 1; i >= 0; i--)
        siftDown(arr, n, i); // build max heap

    for (int end = n - 1; end > 0; end--) {
        int tmp = arr[0]; arr[0] = arr[end]; arr[end] = tmp;
        siftDown(arr, end, 0); // restore heap over shrinking range
    }
}

